"""Offline scientific notes. Scientific wording is translatable; citations retain their published titles.

Source links pin the code reviewed for these notes, rather than silently following dev_max.
Keep REVIEW_COMMIT and each article's implementation notes together when revising the content.
No external documents, web scripts, or network requests are needed to read this module.
"""
from PySide6.QtCore import QCoreApplication

REVIEW_COMMIT = 'a3ae32befd1c4f6a1eaa9bd4b518b6e3d491bcaa'
REPOSITORY = 'https://github.com/OpenSourceNeuro/Spikeling'
DOCS = 'https://opensourceneuro.github.io/Spikeling/'
WEBSITE = 'https://www.opensourceneuro.com/'
SOURCE_ROOT = REPOSITORY + '/blob/' + REVIEW_COMMIT + '/'


def tr(text):
    return QCoreApplication.translate('AboutContent', text)


REFERENCES = {
 'spikeling': dict(authors='Baden, T. and James, B. and Zimmermann, M. J. Y. and Bartel, P. and Grijseels, D. and Euler, T. and Lagnado, L. and Maravall, M.', year='2018', title='Spikeling: A low-cost hardware implementation of a spiking neuron for neuroscience teaching and outreach', journal='PLOS Biology', volume='16', pages='e2006760', doi='10.1371/journal.pbio.2006760'),
 'izhikevich': dict(authors='Izhikevich, E. M.', year='2003', title='Simple model of spiking neurons', journal='IEEE Transactions on Neural Networks', volume='14', pages='1569--1572', doi='10.1109/TNN.2003.820440'),
 'vogelstein': dict(authors='Vogelstein, J. T. and Watson, B. O. and Packer, A. M. and Yuste, R. and Jedynak, B. and Paninski, L.', year='2009', title='Spike Inference from Calcium Imaging Using Sequential Monte Carlo Methods', journal='Biophysical Journal', volume='97', pages='636--655', doi='10.1016/j.bpj.2008.08.005'),
 'wei': dict(authors='Wei, Z. and Lin, B.-J. and Chen, T.-W. and Daie, K. and Svoboda, K. and Druckmann, S.', year='2020', title='A comparison of neuronal population dynamics measured with calcium imaging and electrophysiology', journal='PLOS Computational Biology', volume='16', pages='e1008198', doi='10.1371/journal.pcbi.1008198'),
 'chen': dict(authors='Chen, T.-W. and others', year='2013', title='Ultrasensitive fluorescent proteins for imaging neuronal activity', journal='Nature', volume='499', pages='295--300', doi='10.1038/nature12354'),
 'dana': dict(authors='Dana, H. and others', year='2016', title='Sensitive red protein calcium indicators for imaging neural activity', journal='eLife', volume='5', pages='e12727', doi='10.7554/eLife.12727'),
 'gold': dict(authors='Gold, C. and Henze, D. A. and Koch, C. and Buzsaki, G.', year='2006', title='On the Origin of the Extracellular Action Potential Waveform: A Modeling Study', journal='Journal of Neurophysiology', volume='95', pages='3113--3128', doi='10.1152/jn.00979.2005'),
}


def citation(key):
    r = REFERENCES[key]
    return f"{r['authors']} ({r['year']}). {r['title']}. {r['journal']}, {r['volume']}, {r['pages']}. https://doi.org/{r['doi']}"


def bibtex(key):
    r = REFERENCES[key]
    fields = dict(author=r['authors'], title=r['title'], journal=r['journal'], year=r['year'], volume=r['volume'], pages=r['pages'], doi=r['doi'], url='https://doi.org/'+r['doi'])
    return '@article{spikeling_' + key + ',\n' + ',\n'.join('  '+k+' = {'+v+'}' for k,v in fields.items()) + '\n}\n'


def articles():
    """Return translated articles; all scientific strings use literal translate calls for lupdate."""
    return [
      dict(key='izhikevich', title=QCoreApplication.translate('AboutContent', 'Neuron dynamics · Izhikevich'),
        provenance=QCoreApplication.translate('AboutContent', 'Adapted from Izhikevich (2003); firmware and desktop emulator have separate implementations.'),
        source='Firmware/Spikeling_V3/Core_functions.h',
        overview=QCoreApplication.translate('AboutContent', '<h2>From a compact model to diverse firing patterns</h2><p>The Izhikevich model couples a membrane-voltage variable v to a recovery variable u. Changing a, b, c and d produces different firing behaviours, including adaptation and bursting.</p><p>Spikeling connects this model to current injection, light-sensitive input, noise and two synaptic inputs. The neuron generator lets learners relate parameters to observable behaviour.</p><h3>A question to explore</h3><p>With identical stimulation, how does changing recovery alter the first response and the later firing rate?</p>'),
        equations=QCoreApplication.translate('AboutContent', '<h2>Core equations</h2><p>dv/dt = 0.04v² + 5v + 140 − u + I</p><p>du/dt = a(bv − u)</p><p>When v reaches the spike cutoff: v ← c; u ← u + d.</p><h3>Variables and parameters</h3><p>v: model membrane potential; u: recovery variable; a: recovery time-scale parameter; b: coupling to voltage; c: reset voltage; d: recovery increment after a spike.</p><p>I is the summed model input. Current-clamp inputs use model units; do not infer a physical current calibration from these equations alone. The spike cutoff is a numerical event rule, not a complete biological initiation mechanism.</p>'),
        implementation=QCoreApplication.translate('AboutContent', '<h2>Implementation in Spikeling</h2><p>Core_functions.h implements the hardware-facing update and output logic. Izhikevich_parameters.h contains neuron presets; General_settings.h contains timing and state settings. Graph_Emulator.py implements the desktop simulation.</p><p>Model integration time and elapsed wall-clock time are different quantities. Record the timing settings and the chosen hardware or emulator route when comparing experiments.</p><p>Optional pharmacology and voltage clamp add separate paths. The two core equations do not by themselves describe every optional mode.</p>'),
        limitations=QCoreApplication.translate('AboutContent', '<h2>Interpretation</h2><p>This is a phenomenological spiking model. The recovery variable is not a direct measurement of one ion-channel population, and the reset rule does not reproduce a complete action-potential waveform.</p><p>It is well suited to exploring excitability, adaptation and coding. It does not establish preparation-specific ion-channel kinetics, dendritic morphology or quantitative drug responses.</p>'),
        refs=[('izhikevich','adapted'),('spikeling','background')]),
      dict(key='synapses', title=QCoreApplication.translate('AboutContent', 'Synapses & short-term plasticity'),
        provenance=QCoreApplication.translate('AboutContent', 'Educational implementation; event-driven, simplified Tsodyks–Markram-style resource model.'), source='Firmware/Spikeling_V3/STP_functions.h',
        overview=QCoreApplication.translate('AboutContent', '<h2>Timing and recent activity shape synaptic responses</h2><p>Each synapse combines a signed gain with a decaying response. Positive and negative gain support excitation and inhibition. Short-term plasticity changes event strength according to recent presynaptic activity.</p><p>Off, combined, facilitation and depression modes are independently selected for the two synapses.</p><h3>A question to explore</h3><p>How does the second response change as the interval between two presynaptic spikes increases?</p>'),
        equations=QCoreApplication.translate('AboutContent', '<h2>Event-driven state updates</h2><p>Between events separated by Δt:</p><p>u ← U + (u − U) exp(−Δt/τF)</p><p>x ← 1 − (1 − x) exp(−Δt/τD)</p><p>Event multiplier M = (u/U)x.</p><p>After the event, enabled depletion consumes resources: x ← x(1 − u). Enabled facilitation increases utilisation: u ← u + U(1 − u).</p><p>U: baseline utilisation; x: available resource fraction; τF and τD: recovery time constants in ms. Disabled processes follow their explicit branches in the implementation.</p>'),
        implementation=QCoreApplication.translate('AboutContent', '<h2>Implementation in Spikeling</h2><p>STP_functions.h updates the states at incoming spike events using simulated elapsed time. The normalisation makes the fully recovered first response equal to the original gain.</p><p>Core_functions.h combines the event multiplier with the synaptic input. Pharmacology_functions.h contains the separate optional probabilistic-release route. Stochastic release and short-term resource dynamics are distinct mechanisms.</p>'),
        limitations=QCoreApplication.translate('AboutContent', '<h2>Interpretation</h2><p>The resource variables are effective states, not direct measurements of vesicle pools. Preset values are teaching choices. Short-term facilitation and depression do not imply long-term potentiation or depression.</p><p>Analogue presynaptic voltage and digital spike events represent different input routes. Interpret the response in the context of the route actually used.</p>'), refs=[('spikeling','background')]),
      dict(key='clamp', title=QCoreApplication.translate('AboutContent', 'Current clamp & voltage clamp'),
        provenance=QCoreApplication.translate('AboutContent', 'Educational implementation; passive circuit and separate active conductance-based membrane.'),source='Firmware/Spikeling_V3/VoltageClamp_functions.h',
        overview=QCoreApplication.translate('AboutContent', '<h2>Two ways of asking a neuron a question</h2><p>Current clamp changes the input current and observes voltage. Voltage clamp sets a voltage command and reports the current required by the clamp model.</p><p>The passive membrane exposes leak and capacitive behaviour. The active membrane adds voltage-dependent currents. The CC/VC selector changes the meaning of the patch control.</p><h3>A question to explore</h3><p>Which parts of a voltage-step response remain after switching from an active to a passive membrane?</p>'),
        equations=QCoreApplication.translate('AboutContent', '<h2>Passive circuit relationships</h2><p>Ileak = (Vm − Eleak)/Rm</p><p>Iaccess = (Vcmd − Vm)/Rs</p><p>The membrane charge balance includes capacitance, leak, applied inputs and any enabled conductance terms.</p><p>With mV and MΩ, the resistance expressions yield nA. The implementation explicitly converts capacitance and time units. Read its current signs and exported sample fields before interpreting the recorded total.</p><p>The active path adds sodium and potassium terms; it is not obtained by imposing a command voltage on the Izhikevich reset equations.</p>'),
        implementation=QCoreApplication.translate('AboutContent', '<h2>Implementation in Spikeling</h2><p>VoltageClamp_functions.h contains the passive and active cells, ideal/access modes, current limits and numerical stepping. Core_functions.h routes the command, inputs and exported sample values.</p><p>External stimulation remains part of the experimental input route. The About page never sends clamp commands or changes a running experiment.</p>'),
        limitations=QCoreApplication.translate('AboutContent', '<h2>Interpretation</h2><p>Access resistance and current limits can prevent Vm from reaching the command. Check the mode and saturation before interpreting a response.</p><p>The active VC membrane and current-clamp Izhikevich model are different representations. Their responses should not be treated as measurements from an identical detailed biological cell.</p>'),refs=[]),
      dict(key='pharmacology', title=QCoreApplication.translate('AboutContent', 'Pharmacology & probabilistic release'),
        provenance=QCoreApplication.translate('AboutContent', 'Phenomenological educational extension; not a preparation-specific pharmacokinetic model.'),source='Firmware/Spikeling_V3/Pharmacology_functions.h',
        overview=QCoreApplication.translate('AboutContent', '<h2>Use perturbations to test a mechanism</h2><p>The optional module includes TTX, TEA, apamin, 4-AP, NBQX, gabazine, APV and GVIA. Their actions are represented through effective availability, intrinsic excitability, synaptic and release terms.</p><p>Probabilistic release introduces trial-to-trial variation at incoming presynaptic events.</p><h3>A question to explore</h3><p>Can a smaller postsynaptic response be explained by weaker release, altered receptors or changed intrinsic excitability? Which control experiment would distinguish them?</p>'),
        equations=QCoreApplication.translate('AboutContent', '<h2>Effective availability and release</h2><p>The implementation precomputes Hill-type concentration-response blockade. Concentration units and target mapping are drug-specific and must be taken from the corresponding parameter definitions.</p><p>For N release sites with probability p, a binomial release variable K has E[K] = Np and Var[K] = Np(1 − p). The delivered event is then scaled according to the implementation.</p><p>The random seed controls the pseudo-random sequence. Identical seeds reproduce a sequence only with the same code, state and event ordering.</p>'),
        implementation=QCoreApplication.translate('AboutContent', '<h2>Implementation in Spikeling</h2><p>Pharmacology_functions.h owns drug concentrations, blockade, intrinsic states, receptor currents and release state. Serial command registration remains in Serial_functions.h.</p><p>The firmware can infer receptor identity from the effective signed synaptic gain. CC and active VC use different membrane representations; consult both paths when interpreting an effect.</p>'),
        limitations=QCoreApplication.translate('AboutContent', '<h2>Interpretation</h2><p>A named simulated drug is a teaching perturbation. Its concentration-response curve is not a prediction of the dose required for a particular biological preparation.</p><p>Effects depend on enabled pathways, synaptic sign and membrane mode. Absence of a visible change does not establish absence of a biological target. The original Spikeling publication does not validate these later extensions.</p>'),refs=[]),
      dict(key='imaging', title=QCoreApplication.translate('AboutContent', 'Calcium & fluorescence'),
        provenance=QCoreApplication.translate('AboutContent', 'Adapted forward-model concepts; distinguish calcium dynamics, indicator response and acquisition.'),source='Software/GUI - PyQt6-PySide6/Graph_Imaging.py',
        overview=QCoreApplication.translate('AboutContent', '<h2>From spikes to an indirect optical readout</h2><p>Vm → detected spikes → calcium dynamics → indicator response → frame-sampled fluorescence.</p><p>Spikes are detected using an upward voltage-threshold crossing and a refractory interval. Calcium and indicator states are updated from incoming samples; fluorescence is observed at camera-frame boundaries and held between frames.</p><h3>A question to explore</h3><p>Compare a spike train and its fluorescence at two frame rates. Which events remain distinguishable, and which merge?</p>'),
        equations=QCoreApplication.translate('AboutContent', '<h2>Calcium rise/decay kernel</h2><p>τdr = τdτr/(τd + τr)</p><p>xd ← xd exp(−Δt/τd) + A·spike</p><p>xdr ← xdr exp(−Δt/τdr) + A·spike</p><p>C = max(0, Cbaseline + xd − xdr + noise)</p><p>Calcium is expressed in µM; these time constants and Δt are in ms.</p><h2>Indicator and fluorescence</h2><p>Equilibrium Hill option: S = Cⁿ/(Cⁿ + Kdⁿ).</p><p>Optional kinetic binding: dSb/dt = kon(Stotal − Sb)Cⁿ − koffSb, using seconds for integration.</p><p>Linear: Fmean = offset + gain·α(C + β).</p><p>Saturating: Fmean = offset + gain·(1 + dffmax·S).</p><p>gain includes optical scaling and the bleaching factor. Observation noise is added at frame times.</p>'),
        implementation=QCoreApplication.translate('AboutContent', '<h2>Implementation in Spikeling</h2><p>Graph_Imaging.py contains spike detection, the two-state calcium kernel, Hill/logistic or kinetic indicator options, frame sampling and observation noise. Parameters_GECI.py supplies indicator presets.</p><p>The displayed ΔF/F0 uses an offset-corrected reference based on baseline calcium and gain. The baseline reference excludes stochastic noise and the dynamic bleaching factor, so bleaching can remain visible as drift.</p><p>Wei-style S2F concepts inform the rise/decay kernel; Vogelstein-style concepts inform the linear observation route. These are adaptations, not complete reproductions of the cited inference methods. The optional binding ODE is documented from the code; this bibliography does not assign an unverified paper to it.</p>'),
        limitations=QCoreApplication.translate('AboutContent', '<h2>Interpretation</h2><p>Indicator presets combine effective kinetics and biochemical quantities that depend on assay conditions. A preset name does not imply quantitative validation of every parameter or the entire simulated optical trace.</p><p>The simulator uses a reduced calcium and optical model. It does not simulate spatial calcium diffusion, full photon statistics, microscope optics or a preparation-specific camera.</p><p>Clamping of states, threshold-based spike detection and finite input sampling affect the result. The saturating expression relative to apo fluorescence should not be confused with ΔF/F0 relative to the chosen nonzero calcium baseline.</p>'),refs=[('wei','adapted'),('vogelstein','inspired'),('chen','background'),('dana','background')]),
      dict(key='extracellular', title=QCoreApplication.translate('AboutContent', 'Extracellular signals & tetrodes'),
        provenance=QCoreApplication.translate('AboutContent', 'Inspired by recording principles; reduced waveform and geometric projection surrogate.'),source='Software/GUI - PyQt6-PySide6/Graph_ExtraCellular.py',
        overview=QCoreApplication.translate('AboutContent', '<h2>One neuron, different views across contacts</h2><p>The extracellular simulator transforms membrane activity and detected spike times into a four-contact tetrode recording. Geometry changes the contribution of a source to each channel.</p><p>Template and derivative-based modes let learners explore waveform differences, noise, reference choice and the information available for spike sorting.</p><h3>A question to explore</h3><p>Move a source relative to the tetrode. Does its largest channel remain the same, and how does that affect unit identification?</p>'),
        equations=QCoreApplication.translate('AboutContent', '<h2>Reduced forward-model structure</h2><p>Channel signal = sum of geometrically weighted source waveforms + independent noise + shared noise + hum.</p><p>Template mode uses a canonical extracellular waveform at spike events. The alternative uses a smoothed voltage derivative gated around detected spikes.</p><p>Optional common-average referencing subtracts the contact mean. Display bandpass filtering is part of the recording chain. Exact weighting, filtering and normalisation are defined in Graph_ExtraCellular.py.</p>'),
        implementation=QCoreApplication.translate('AboutContent', '<h2>Implementation in Spikeling</h2><p>Graph_ExtraCellular.py constructs source waveforms, projects them onto four contacts and applies the recording chain. Tetrode.py provides the spatial interface.</p><p>Gold et al. provides scientific background for geometry-dependent extracellular waveforms. Spikeling does not implement that paper’s full morphology-based forward solution.</p>'),
        limitations=QCoreApplication.translate('AboutContent', '<h2>Interpretation</h2><p>A membrane-voltage derivative is an educational surrogate, not the full extracellular field generated by distributed transmembrane currents.</p><p>The reduced sources do not establish realistic morphology, tissue conductivity or absolute extracellular amplitudes. Use the simulation to reason about geometry, overlap and measurement limitations.</p>'),refs=[('gold','background')]),
      dict(key='analysis', title=QCoreApplication.translate('AboutContent', 'Stimulation, recording & analysis'),
        provenance=QCoreApplication.translate('AboutContent', 'Experimental workflow and software methods; interpretation depends on timing and configuration.'),source='Software/GUI - PyQt6-PySide6/Page_Spikeling_DataAnalysis.py',
        overview=QCoreApplication.translate('AboutContent', '<h2>Turn an observation into a reproducible experiment</h2><p>Define a stimulus, select the model and mode, record the response, inspect signal quality, and choose an analysis that answers the experimental question.</p><p>Keep the waveform, loop count, parameters, software/firmware versions and time convention alongside each recording.</p><h3>A question to explore</h3><p>Does a larger response reflect a change in firing rate, spike timing or trial reliability? Choose a measure before comparing conditions.</p>'),
        equations=QCoreApplication.translate('AboutContent', '<h2>Useful definitions</h2><p>Mean firing rate = detected spike count / observation duration.</p><p>Trial mean at aligned time t = sum of the N aligned responses at t / N.</p><p>These are definitions, not promises that every analysis option uses an identical detector or time window. Inspect threshold, refractory settings, alignment and units in the selected analysis route.</p>'),
        implementation=QCoreApplication.translate('AboutContent', '<h2>Implementation in Spikeling</h2><p>Page_StimulusGenerator.py defines custom stimulus workflows. Graph_Spikeling.py manages neuron recordings, and Page_Spikeling_DataAnalysis.py handles the analysis view.</p><p>The imaging and extracellular views have their own transformation and recording paths. The About documentation records the reviewed source revision; it does not identify the firmware flashed onto a connected board.</p>'),
        limitations=QCoreApplication.translate('AboutContent', '<h2>Interpretation</h2><p>Sampling, missed events, interrupted streams, trial alignment and selected analysis windows can change conclusions. Repeated measurements require the same stimulus and a clearly defined comparison.</p><p>Exporting a CSV alone may not preserve every experimental setting. Retain configuration and provenance alongside the data. This About update does not add an experiment-configuration export feature.</p>'),refs=[('spikeling','background')]),
    ]


def science_text():
    return QCoreApplication.translate('AboutContent', '<h1>Open science in practice</h1><p>Spikeling combines inspectable hardware, firmware and software with teaching materials that educators can adapt.</p><h2>Inspect and reuse</h2><p>Source code and hardware designs are available in the project repository. Software and firmware are distributed under GNU GPL v3; the repository includes GPL-3.0-or-later notices. Hardware uses CERN-OHL-S v2. Check the licence and notices applying to each file before reuse.</p><h2>Reproduce an experiment</h2><p>Keep the GUI and firmware versions, hardware revision when known, model parameters, clamp mode, stimulus file, repetition count, input routes, timing settings and random seeds with the recording. Document any dropped samples or interrupted streams.</p><h2>Understand provenance</h2><p><b>Implemented from:</b> follows the cited formulation. <b>Adapted from:</b> includes documented changes. <b>Inspired by:</b> an educational approximation informed by the work. <b>Background reading:</b> contextual evidence, not a claim of implementation or validation.</p><h2>Contribute</h2><p>Report reproducible bugs with versions, expected behaviour and steps to reproduce. Contributions can include code, hardware, translations, references, protocols and teaching material. Share recordings only when you intend their contents and metadata to be public.</p><h2>Cite the project and the method</h2><p>Cite the Spikeling publication and repository release used. Also cite the model or measurement method relevant to the experiment. A reference does not by itself validate a later software extension.</p>')
